'use strict';
// Original learning companion. Existing book storage remains in app.js.
let learning={bridges:[],projects:[]}, philosophy={lenses:[],essay:[],realityChecks:[]}, frontierData={frontiers:[]};
const JOURNEY_KEY='builders-atlas-journey-v2';
let journeyState={active:'algebra',practiced:[],entries:[],budget:15};
let labMode='arm', labAngle=30, labLength=20, labEffort=0.3, labLoad=20, ideaIndex=0;
const nightTitles=['We Are Legion (We Are Bob)','All Systems Red','Delta-v','The Player of Games','Project Hail Mary'];
const bridgeReading={algebra:['College Algebra 2e','Making Things Move'],functions:['College Algebra 2e','Thinking in Systems'],trigonometry:['Precalculus','Modern Robotics'],vectors:['Introduction to Flight','The Simple Science of Flight'],derivatives:['Calculus','A Mind for Numbers'],integrals:['Calculus','Packing for Mars'],'differential-equations':['Feedback Systems','Introduction to Flight'],'linear-algebra':['Robot Modeling and Control','Modern Robotics'],'free-body':['Structures','The Simple Science of Flight'],statistics:['Measurement','To Engineer Is Human'],'writing-ge':['The Art of Doing Science and Engineering','The Checklist Manifesto'],'materials-manufacturing':['The Perfectionists','The New Science of Strong Materials']};
function ext(s){return `<a class="source-chip" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)} ↗</a>`;}
function v2head(kicker,title,lead){return `<section class="page-head v2-head"><span class="eyebrow">${kicker}</span><h1>${title}</h1><p class="lead">${lead}</p></section>`;}
function activeBridge(){return learning.bridges.find(b=>b.id===journeyState.active)||learning.bridges[0];}
function loadJourney(){try{journeyState=cleanJourney(JSON.parse(localStorage.getItem(JOURNEY_KEY)||'{}'));}catch{journeyState={active:'algebra',practiced:[],entries:[],budget:15};}}
function cleanJourney(v){if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid journal');if(Array.isArray(v.entries)&&v.entries.length>300)throw Error('Capacity');const ids=learning.bridges.map(b=>b.id);return {active:ids.includes(v.active)?v.active:'algebra',budget:[5,15,45].includes(Number(v.budget))?Number(v.budget):15,practiced:Array.isArray(v.practiced)?[...new Set(v.practiced.filter(id=>ids.includes(id)))]:[],entries:Array.isArray(v.entries)?v.entries.filter(x=>x&&typeof x.text==='string'&&typeof x.date==='string').slice(0,300).map((x,i)=>({id:typeof x.id==='string'&&x.id.trim()?x.id.slice(0,100):'import-'+i,date:x.date.slice(0,40),text:x.text.slice(0,5000),kind:['practice','build','question','reflection'].includes(x.kind)?x.kind:'reflection'})):[]};}
function persistJourney(){try{localStorage.setItem(JOURNEY_KEY,JSON.stringify(journeyState));return true;}catch{toast('Saved for this session only. Browser storage is unavailable; export a backup before leaving.');return false;}}
function heroV2(){return `<section class="horizon-hero"><img class="horizon-image" src="assets/orbital-shipyard.png" alt="Speculative orbital shipyard with robotic arms assembling a habitat above Earth"><div class="horizon-shade"></div><div class="hero-coordinate">FIELD GUIDE / 03 <span>THE LONG GAME</span></div><div class="horizon-copy"><span class="eyebrow"><i class="signal-dot"></i> FOR THE ENGINEER YOU’RE BECOMING</span><h1>Keep the future<br><em>in sight.</em></h1><p>Even when tonight is just algebra.</p><div class="horizon-intro">Machines that build. Places to live. Worlds worth exploring. <br>A home for the knowledge, stories, and questions that keep you going.</div><div class="hero-buttons"><a href="#journey" class="btn">Find your next small step <span>↗</span></a><a class="text-link" href="#frontiers">Explore the possible →</a></div></div><div class="hero-bottom"><span>FROM A NOTEBOOK ON EARTH<br>TO THE MACHINES THAT COME NEXT</span><span>ORIGINAL CONCEPT ART<br>SPECULATIVE ORBITAL CONSTRUCTION</span></div></section>`;}
function basecamp(){const b=activeBridge();return heroV2()+atlasTeaser()+`<div class="launch-strip"><a href="#journey"><b>01</b><span>UNDERSTAND THE WORK<strong>Why this class matters</strong></span><i>↗</i></a><a href="#night"><b>02</b><span>EXPAND THE HORIZON<strong>A good story tonight</strong></span><i>↗</i></a><a href="#ideas"><b>03</b><span>EXAMINE THE PURPOSE<strong>What is worth building?</strong></span><i>↗</i></a></div><section class="section daily-section"><div class="section-head"><div><span class="eyebrow">YOUR BASECAMP / COME BACK AS YOU ARE</span><h2>The next step can be small.</h2></div><a class="text-link" href="#journal">Open your field notes ↗</a></div><div class="daily-grid"><div class="daily-main"><div class="panel-top"><span class="eyebrow">CURRENT THREAD</span><span class="small-tag">${journeyState.practiced.length} / 12 EXPLORED</span></div><h3>${esc(b?.title||'Algebra → making the parts fit')}</h3><p>${esc(b?.hook||'Begin with one useful connection.')}</p><a class="btn small" href="#lesson/${b?.id||'algebra'}">Open your learning bridge ↗</a></div><div class="daily-budget"><span class="eyebrow">HOW MUCH ROOM DO YOU HAVE?</span><div class="time-choices">${[5,15,45].map(t=>`<button data-budget="${t}" class="${journeyState.budget===t?'active':''}" aria-pressed="${journeyState.budget===t}">${t}<small>MIN</small></button>`).join('')}</div><div id="budget-copy">${budgetCopy()}</div></div></div></section><section class="section frontier-preview"><div class="section-head"><div><span class="eyebrow">THE REASON BEHIND THE REPETITIONS</span><h2>What could you help build?</h2></div><p>Five frontiers. Real engineering underneath.<br>Today’s evidence and tomorrow’s possibilities kept in view.</p></div><div class="mission-grid">${frontierData.frontiers.slice(0,3).map(missionCard).join('')}</div><a class="text-link section-end" href="#frontiers">Explore all five frontiers ↗</a></section><section class="equation-teaser"><div><span class="eyebrow">FROM SYMBOLS TO SOMETHING YOU CAN MOVE</span><h2>That triangle<br><em>is a robot arm.</em></h2><p>Turn an angle. Watch a mechanism move. A small interactive workbench connects the equation to a physical result.</p><a class="btn" href="#workbench">Try the interactive workbench ↗</a></div><div class="teaser-diagram">${armSVG(30,20)}<span class="equation-caption">x = L cos θ &nbsp; · &nbsp; y = L sin θ</span></div></section><section class="section"><div class="section-head"><div><span class="eyebrow">THE LIBRARY REMAINS AT THE HEART OF IT</span><h2>${books.length} doors into a bigger world.</h2></div><a class="text-link" href="#library">Search the whole library ↗</a></div>${cards(['Structures','The Player of Games','The Knowledge','All Systems Red'].map(findBook).filter(Boolean))}<div class="library-links"><a href="#paths">${paths.length} guided reading routes →</a><a href="#banks">Your guide to Iain M. Banks →</a><a href="#night">Fiction for the end of the day →</a></div></section><section class="thought-band"><span class="eyebrow">AMBITION / AGENCY / ACCOUNTABILITY</span><h2>Powerful machines.<br><em>Worthwhile purposes.</em></h2><p>Thiel asks what new capability you can create. Karp asks what public purpose technology should serve. Banks asks what abundance makes possible. Bring your own judgment to all three.</p><a href="#ideas" class="text-link">Enter the big questions ↗</a></section>`;}
function budgetCopy(){return ({5:'<strong>Reconnect.</strong><p>Read one learning bridge or a few pages of fiction. Leave one question for next time.</p>',15:'<strong>Make one idea concrete.</strong><p>Try a worked example, check your answer, then explain it once in your own words.</p>',45:'<strong>Practice, then experiment.</strong><p>Use most of the block for your actual coursework. Finish with a small model or project note that shows what it connects to.</p>'})[journeyState.budget];}
function journeyPage(){return v2head('YOUR JOURNEY / CAPABILITY COMES IN LAYERS','The work beneath<br><em>the wonder.</em>','Starting out, changing direction, or revisiting an old subject? These bridges connect coursework to engineering. Build careful habits, explore what interests you, and keep an actual degree plan separate from this conceptual guide.')+`<section class="section route-map"><div class="phase-track">${[['01','FOUNDATIONS','Algebra, functions, trig, writing','Learn to represent a problem clearly.'],['02','TRANSFER PREPARATION','Calculus, physics, programming, design','Build the prerequisites your target program actually requires.'],['03','ENGINEERING DEPTH','Mechanics, fluids, structures, controls','Model, build, test, and work in a team.'],['04','A DIRECTION OF YOUR OWN','Industry, graduate study, research','Choose a problem worth sustained attention.']].map(([n,t,s,p])=>`<article><span>${n}</span><h3>${t}</h3><strong>${s}</strong><p>${p}</p></article>`).join('')}</div><p class="note">A conceptual map, not an official course schedule or promised transfer date. Confirm current prerequisites and articulation with your college and destination program.</p></section><section class="section" style="padding-top:20px"><div class="section-head"><div><span class="eyebrow">12 LEARNING BRIDGES</span><h2>Find the point of the subject.</h2></div><p>Start with algebra. Later topics are previews.<br>“Explored” means you tried the example, not that you mastered the course.</p></div><div class="bridge-grid">${learning.bridges.map((b,i)=>`<a href="#lesson/${b.id}" class="bridge-card ${journeyState.practiced.includes(b.id)?'explored':''}"><div class="panel-top"><span class="eyebrow">${String(i+1).padStart(2,'0')}</span><span>${journeyState.practiced.includes(b.id)?'✓ EXPLORED':'↗'}</span></div><h3>${esc(b.title)}</h3><p>${esc(b.hook)}</p></a>`).join('')}</div></section><section class="section ground-note"><span class="eyebrow">WHEN THE CLASS FEELS POINTLESS</span><h2>You don’t have to love every assignment.</h2><p>Extract one capability from it. Algebra gives you ways to express constraints. Writing gives you ways to explain evidence. History helps you ask why institutions adopted one technology and rejected another. General education can widen the questions you bring to technical work.</p><p>Some assignments will still feel tedious. A sustainable week can contain careful work, family time, enjoyable reading, and ordinary rest. You do not have to turn every free hour into a credential.</p><a href="#projects" class="text-link">Bring an idea to the workbench ↗</a></section>`;}
function lessonPage(id){const b=learning.bridges.find(x=>x.id===id);if(!b)return notFound();const i=learning.bridges.indexOf(b);const paired=(bridgeReading[id]||[]).map(findBook).filter(Boolean);return v2head(`LEARNING BRIDGE ${String(i+1).padStart(2,'0')} / ${learning.bridges.length}`,esc(b.title),esc(b.hook))+`<section class="section lesson-layout"><aside class="lesson-nav"><a href="#journey">← All learning bridges</a>${learning.bridges.map((x,j)=>`<a href="#lesson/${x.id}" ${x.id===id?'aria-current="page"':''}><span>${String(j+1).padStart(2,'0')}</span>${esc(x.title.split(' → ')[0])}</a>`).join('')}</aside><article class="lesson-body"><div class="future-use"><span class="eyebrow">WHERE THIS GOES</span><p>${esc(b.future)}</p></div><h2>Make it concrete.</h2><p>${esc(b.lesson)}</p><div class="practice-box"><span class="eyebrow">TRY IT BEFORE YOU OPEN THE ANSWER</span><h3>${esc(b.question)}</h3><details><summary>Reveal the reasoning</summary><p>${esc(b.answer)}</p></details></div><h2>Put your hands on the idea.</h2><p>${esc(b.activity)}</p>${['trigonometry','algebra','free-body'].includes(id)?'<a href="#workbench" class="text-link">Experiment in the interactive workbench →</a>':''}<div class="lesson-actions"><button class="btn small" data-practice="${id}" aria-pressed="${journeyState.practiced.includes(id)}">${journeyState.practiced.includes(id)?'✓ Explored · mark untried':'I tried the example ✓'}</button><button class="btn small light" data-active-bridge="${id}">Make this my current thread</button></div><p class="note">Self-reported exploration, not a mastery score. Revisit as often as useful.</p>${ext(b.source)}<p class="note">Original worked example and application. The linked source teaches the underlying principle.</p>${paired.length?`<h2>Books to grow with.</h2><div class="lesson-books">${paired.map(x=>`<button data-open="${x.id}"><span>${esc(x.stage)}</span><strong>${esc(x.title)}</strong><small>${esc(x.author)} ↗</small></button>`).join('')}</div>`:''}<div class="next-lesson">${i>0?`<a href="#lesson/${learning.bridges[i-1].id}">← Previous bridge</a>`:'<span></span>'}${i<learning.bridges.length-1?`<a href="#lesson/${learning.bridges[i+1].id}">Next bridge →</a>`:'<a href="#projects">Try a project →</a>'}</div></article></section>`;}
function missionArt(i){const styles=['orbital','lunar','factory','ocean','flight'];return `<div class="mission-art ${styles[i%5]}" aria-hidden="true">${glyph([0,1,3,4,2][i%5])}<span>FIELD / ${String(i+1).padStart(2,'0')}</span></div>`;}
function missionCard(f,i){return `<a class="mission-card" href="#frontier/${f.id}">${missionArt(i)}<div><span class="eyebrow">${esc(f.kicker)}</span><h3>${esc(f.title)}</h3><p>${esc(f.summary)}</p><span class="text-link">Open the dossier ↗</span></div></a>`;}
function frontiersPage(){return v2head('FRONTIERS / THE MACHINERY OF POSSIBILITY','Bigger futures.<br><em>Real dependencies.</em>','Start with what works today. Follow the difficult steps toward what might work next. Aerospace and related engineering disciplines contribute to parts of these systems; no one person has to build an entire civilization.')+`<section class="section" style="padding-top:15px"><div class="mission-grid all-missions">${frontierData.frontiers.map(missionCard).join('')}</div></section><section class="section"><div class="section-head"><div><span class="eyebrow">LEARN TO READ THE HEADLINE</span><h2>A breakthrough is a beginning.</h2></div><p>Ask what was demonstrated, under what conditions,<br>and which dependencies remain outside the frame.</p></div><div class="reality-grid">${philosophy.realityChecks.map(r=>`<article><span class="small-tag">${esc(r.status)}</span><h3>${esc(r.title)}</h3><p>${esc(r.body)}</p><blockquote>${esc(r.question)}</blockquote>${ext(r.source)}</article>`).join('')}</div></section>`;}
function frontierPage(id){const f=frontierData.frontiers.find(x=>x.id===id);if(!f)return notFound();return v2head(esc(f.kicker),esc(f.title),esc(f.summary))+`<section class="section dossier"><div class="dossier-banner">${missionArt(frontierData.frontiers.indexOf(f))}<div><span class="eyebrow">THE HARD PART</span><h2>${esc(f.hardProblem)}</h2></div></div><div class="readiness-grid"><article><span class="readiness today">01 / DEMONSTRATED FOUNDATIONS</span><h3>Where we are.</h3><p>${esc(f.today)}</p></article><article><span class="readiness next">02 / DEVELOPMENT & RESEARCH</span><h3>The next difficult steps.</h3><p>${esc(f.next)}</p></article><article><span class="readiness horizon">03 / SPECULATIVE HORIZON</span><h3>How far it could go.</h3><p>${esc(f.horizon)}</p></article></div><div class="dossier-bottom"><div><span class="eyebrow">YOUR AEROSPACE CONNECTION</span><h3>A place for your skills.</h3><p>${esc(f.degreeConnection)}</p></div><div><span class="eyebrow">A FIRST STEP FROM HERE</span><h3>Make it smaller. Make it real.</h3><p>${esc(f.firstStep)}</p><a href="#projects" class="text-link">Explore beginner projects →</a></div></div><div class="dossier-sources"><span class="eyebrow">READ THE EVIDENCE</span>${f.sources.map(ext).join('')}</div><a class="text-link" href="#frontiers">← Back to the five frontiers</a></section>`;}
function ideasPage(){return v2head('BIG QUESTIONS / PHILOSOPHY FOR A BUILDER','What is worth<br><em>building?</em>',esc(philosophy.intro))+`<section class="section" style="padding-top:12px"><div class="thinker-tabs" role="group" aria-label="Choose a philosophical lens">${philosophy.lenses.map((l,i)=>`<button data-lens="${i}" aria-pressed="${i===ideaIndex}" class="${i===ideaIndex?'active':''}"><span>0${i+1}</span>${esc(l.thinker.split(' · ')[0].split(' with ')[0].split(' and ')[0])}</button>`).join('')}</div><div id="idea-panel">${lensPanel()}</div></section><section class="section essay-section"><div class="essay-aside"><span class="eyebrow">A SHORT ESSAY</span><h2>Ambition that<br>can answer<br><em>questions.</em></h2><p>Technical depth and philosophical judgment can develop together. Neither makes the other unnecessary.</p><a class="text-link" href="#journal">Keep a question in your notes →</a></div><div class="essay-body">${philosophy.essay.map((p,i)=>`<article><span>0${i+1}</span><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p></article>`).join('')}</div></section><section class="section ground-note"><span class="eyebrow">ROOM FOR QUESTIONS WITH NO PRODUCTIVITY PAYOFF</span><h2>A finite life. A very long future.</h2><p>Which ambitions would still matter if nobody applauded? What would you protect in a civilization with extraordinary machines? What do friendship, beauty, play, and belonging contribute to a life that is already productive?</p><p>You can be serious about building and leave some questions open. A novel can be an evening well spent even when it produces no project plan.</p><a class="text-link" href="#night">Find tonight’s story ↗</a></section>`;}
function lensPanel(){const l=philosophy.lenses[ideaIndex];if(!l)return '';return `<article class="lens-panel"><div class="lens-title"><span class="eyebrow">LENS 0${ideaIndex+1}</span><h2>${esc(l.title)}</h2><p>${esc(l.thinker)}</p>${ext(l.source)}</div><div class="lens-content"><div><span class="eyebrow">THE ARGUMENT</span><p>${esc(l.thesis)}</p></div><div><span class="eyebrow">BRING IT TO ENGINEERING</span><p>${esc(l.useful)}</p></div><div><span class="eyebrow">LET IT MEET A COUNTERQUESTION</span><p>${esc(l.tension)}</p></div><blockquote>${esc(l.question)}</blockquote><p class="note">Arguments are attributed; applications and counterquestions are editorial. These perspectives are invitations to examine, not a statement of your beliefs.</p></div></article>`;}
function nightPage(){const bs=nightTitles.map(findBook).filter(Boolean);return v2head('NIGHT READING / OFF THE CLOCK','Let a story<br><em>carry you somewhere.</em>','A shelf for the end of the day: suspense, machine minds, builders, and strange worlds. Read on a screen or on paper. No exercises. No requirement to make leisure useful.')+`<section class="section night-intro"><div class="night-orbit" aria-hidden="true"><span>☾</span><i></i></div><div><span class="eyebrow">A TECHNO-THRILLER STARTING POINT</span><h2>Daemon.</h2><p>Daniel Suarez’s <em>Daemon</em> is a starting point for readers drawn to software spilling into the physical world. Try the author’s overview, borrow a copy, or start with a book already on your shelf. Then choose the flavor you want next.</p><a class="btn small" href="https://daniel-suarez.com/daemonsynopsis.html" target="_blank" rel="noopener">Daemon · the author’s story overview ↗</a><p class="note">Now part of the expanded catalog. The link opens the author’s own overview.</p></div></section><section class="section" style="padding-top:20px"><div class="night-menu">${[['Builder adventure','We Are Legion (We Are Bob)','Identity, probes, and a playful engineering imagination.'],['Short robot story','All Systems Red','A compact doorway into autonomy and personhood.'],['Industrial space suspense','Delta-v','Building a space economy with pressure, tradeoffs, and human stakes.'],['Civilization-scale possibility','The Player of Games','Your accessible entry into Banks’s Culture.']].map(([m,t,d])=>`<button data-open="${findBook(t)?.id||''}"><span class="eyebrow">${m}</span><h3>${t}</h3><p>${d}</p><span class="text-link">Explore →</span></button>`).join('')}</div></section><section class="section"><div class="section-head"><div><span class="eyebrow">A SMALL NIGHTSTAND</span><h2>Choose by curiosity.</h2></div><a href="#banks" class="text-link">The full Banks guide ↗</a></div>${cards(bs)}<p class="note section-end">These are adult selections. Reading demand is an editorial estimate; pick a lighter book or put one down whenever it suits you. For denser horizons later: <em>Seveneves</em>, <em>Blindsight</em>, and <em>Excession</em>.</p></section>`;}
function armSVG(angle,length){const rad=angle*Math.PI/180,x=length*Math.cos(rad),y=length*Math.sin(rad),sx=80+x*5,sy=245-y*5;return `<svg viewBox="0 0 430 290" role="img" aria-label="${length} centimeter robot link at ${angle} degrees. Tip x ${x.toFixed(1)} centimeters, y ${y.toFixed(1)} centimeters."><defs><pattern id="lab-grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="currentColor" opacity=".12"/></pattern></defs><rect x="30" y="20" width="370" height="250" fill="url(#lab-grid)"/><g stroke="currentColor" fill="none"><path d="M50 245H405M80 270V15" opacity=".45"/><path d="M80 245H${sx.toFixed(2)}V${sy.toFixed(2)}" stroke-dasharray="4 5" stroke-width="2" opacity=".65"/><path d="M80 245L${sx.toFixed(2)} ${sy.toFixed(2)}" stroke="#d6ad71" stroke-width="10" stroke-linecap="round"/><circle cx="80" cy="245" r="15" fill="#152526" stroke="#d6ad71" stroke-width="3"/><circle cx="${sx.toFixed(2)}" cy="${sy.toFixed(2)}" r="9" fill="#e8ce9e" stroke="#0c1a1b" stroke-width="3"/></g><g fill="currentColor" font-family="Consolas,monospace" font-size="12"><text x="393" y="264">x</text><text x="62" y="23">y</text><text x="110" y="232">${angle}°</text><text x="165" y="280">${x.toFixed(1)} cm across</text><text x="125" y="28">${y.toFixed(1)} cm up</text></g></svg>`;}
function leverSVG(effort,load){const e=Number(effort),f=Number(load),required=f*0.1/e;return `<svg viewBox="0 0 430 290" role="img" aria-label="A balanced ideal lever needs ${required.toFixed(1)} newtons effort to balance a ${f} newton load."><path d="M40 240H390" stroke="currentColor" opacity=".2"/><path d="M160 230l25-65 25 65z" fill="none" stroke="#9ac8c0" stroke-width="3"/><path d="M${185-e*260} 160H${211}" stroke="#d6ad71" stroke-width="10" stroke-linecap="round"/><path d="M${185-e*260} 60v85m-7-10 7 10 7-10M211 65v80m-7-10 7 10 7-10" fill="none" stroke="currentColor" stroke-width="2"/><g fill="currentColor" font-family="Consolas,monospace" font-size="13"><text x="25" y="45">EFFORT: ${required.toFixed(1)} N</text><text x="225" y="85">LOAD: ${f} N</text><text x="25" y="265">${e.toFixed(2)} m effort arm · 0.10 m load arm</text></g></svg>`;}
function workbenchPage(){return v2head('THE INTERACTIVE WORKBENCH / MODELS YOU CAN TOUCH','Move a control.<br><em>Meet the equation.</em>','Two deliberately simple models. Change one input, predict the result, then check what happened. These are educational sketches, with assumptions exposed.')+`<section class="section" style="padding-top:10px"><div class="segmented lab-tabs"><button data-lab="arm" class="${labMode==='arm'?'active':''}" aria-pressed="${labMode==='arm'}">01 · Robot reach</button><button data-lab="lever" class="${labMode==='lever'?'active':''}" aria-pressed="${labMode==='lever'}">02 · Mechanical advantage</button></div><div id="lab-panel">${labPanel()}</div></section><section class="section ground-note"><span class="eyebrow">THE ENGINEERING HABIT</span><h2>Prediction → observation → revision.</h2><p>Before moving a slider, say what you expect. Afterward, explain the direction and size of the change. Then ask which real-world behavior this model leaves out. That last question is where a clean calculation begins to become engineering judgment.</p><a href="#projects" class="text-link">Try a physical tabletop project ↗</a></section>`;}
function labPanel(){return `<div class="lab-layout"><div class="lab-stage"><div id="lab-visual">${labMode==='arm'?armSVG(labAngle,labLength):leverSVG(labEffort,labLoad)}</div><div class="lab-equation">${labMode==='arm'?'x = L cos θ &nbsp; · &nbsp; y = L sin θ':'F<sub>effort</sub> × d<sub>effort</sub> = F<sub>load</sub> × d<sub>load</sub>'}</div></div><div class="lab-controls">${labMode==='arm'?`<span class="eyebrow">ONE LINK / TWO COORDINATES</span><h2>A length becomes<br>across and up.</h2><label for="lab-angle">Joint angle <output id="angle-output">${labAngle}°</output></label><input id="lab-angle" type="range" min="0" max="90" value="${labAngle}" step="1"><label for="lab-length">Link length <output id="length-output">${labLength} cm</output></label><input id="lab-length" type="range" min="10" max="40" value="${labLength}" step="1"><div class="lab-result" id="lab-result">${armResult()}</div><p>Try doubling the length at the same angle. Both coordinates double. Now keep the length fixed and rotate it: reach changes because direction matters.</p><p class="note">Rigid link, fixed pivot, flat plane, degrees. Ignores thickness, joint limits beyond the shown range, collisions, flex, and loads. A schematic, not a robot design tool.</p>${ext({label:'NASA · Vector components',url:'https://www.grc.nasa.gov/www/k-12/rocket/vectpart.html'})}<a href="#lesson/trigonometry" class="text-link">Learn the triangle →</a>`:`<span class="eyebrow">BALANCE / FORCE AND DISTANCE</span><h2>A longer handle.<br>A smaller effort.</h2><label for="lab-effort">Effort arm <output id="effort-output">${labEffort.toFixed(2)} m</output></label><input id="lab-effort" type="range" min="0.1" max="0.5" value="${labEffort}" step="0.01"><label for="lab-load">Load force <output id="load-output">${labLoad} N</output></label><input id="lab-load" type="range" min="10" max="50" value="${labLoad}" step="1"><div class="lab-result" id="lab-result">${leverResult()}</div><p>The load stays 0.10 m from the pivot. Move the effort farther away and less force is required for balance. The trade is a larger movement at the effort end.</p><p class="note">Static balance; forces perpendicular to a massless rigid lever; ideal frictionless pivot. Does not model motion, strength, flex, or losses. The short load arm is drawn to the same scale as the effort arm.</p>${ext({label:'OpenStax · Simple machines',url:'https://openstax.org/books/physics/pages/9-3-simple-machines'})}`}</div></div>`;}
function armResult(){const r=labAngle*Math.PI/180;return `<div><strong>${(labLength*Math.cos(r)).toFixed(1)}<small> cm</small></strong><span>HORIZONTAL / x</span></div><div><strong>${(labLength*Math.sin(r)).toFixed(1)}<small> cm</small></strong><span>VERTICAL / y</span></div>`;}
function leverResult(){return `<div><strong>${(labLoad*.1/labEffort).toFixed(1)}<small> N</small></strong><span>REQUIRED EFFORT FORCE</span></div><div><strong>${(labEffort/.1).toFixed(1)}<small>×</small></strong><span>IDEAL MECHANICAL ADVANTAGE</span></div>`;}
function projectsPage(){return v2head('SMALL BUILDS / PHYSICAL EVIDENCE','Give your curiosity<br><em>a workbench.</em>','Six approachable ways to connect the symbols to materials and motion. Make the first version simple enough that you can understand every part, then change one thing and measure the result.')+`<section class="section projects-grid" style="padding-top:10px">${learning.projects.map((p,i)=>`<article class="project-card"><div class="project-heading"><span class="eyebrow">BUILD / ${String(i+1).padStart(2,'0')}</span>${glyph(i)}<h2>${esc(p.title)}</h2></div><p>${esc(p.summary)}</p><h3>What you need</h3><p>${esc(Array.isArray(p.materials)?p.materials.join(', '):p.materials)}</p><details><summary>Open the build brief</summary><ol>${p.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>What you’re learning</h3><p>${esc(p.learn)}</p><h3>One step further</h3><p>${esc(p.stretch)}</p>${ext(p.source)}</details></article>`).join('')}</section><section class="section ground-note"><span class="eyebrow">A BUILD IS A QUESTION MADE PHYSICAL</span><h2>Keep the imperfect version.</h2><p>Photograph it. Name the assumption that failed. Explain the next change. That small evidence trail is more useful than a polished model you cannot explain. If children join in, choose age-appropriate materials and supervise small parts and tools.</p><a class="text-link" href="#journal">Record what you learned →</a></section>`;}
function journalPage(){return v2head('YOUR FIELD NOTES / EVIDENCE OF A LONGER JOURNEY','Notice what<br><em>is accumulating.</em>','A corrected calculation. A part that finally fits. A question you can now ask more precisely. Keep a small record; there is no streak to protect.')+`<section class="section journal-layout" style="padding-top:10px"><div><div class="journal-counts"><div><strong>${journeyState.practiced.length}</strong><span>BRIDGES EXPLORED</span></div><div><strong>${journeyState.entries.length}</strong><span>FIELD NOTES</span></div></div><form id="journal-form"><label for="entry-kind">What kind of note?</label><select id="entry-kind"><option value="practice">Something I practiced</option><option value="build">Something I built or tested</option><option value="question">A question I want to keep</option><option value="reflection">A reflection</option></select><label for="entry-text">What do you want to remember?</label><textarea id="entry-text" maxlength="5000" required placeholder="What did I try? What happened? What will I do differently?"></textarea><button class="btn" type="submit">Save a field note +</button></form><div class="journal-tools"><button data-export-learning-log>Export learning log for GitHub ↓</button><button data-journey-export>Export journey backup ↓</button><button data-journey-import>Import journey backup ↑</button></div><input type="file" id="journey-import" accept="application/json,.json" hidden><p class="note">Up to 300 field notes, stored only in this browser. New entries and imports stop at the limit without deleting older notes. Export a backup before switching devices or clearing site data. Your book shelf has its own backup in Your shelf.</p></div><div class="journal-entries">${journeyState.entries.length?journeyState.entries.map(e=>`<article><div class="panel-top"><span class="eyebrow">${esc(e.kind)}</span><time>${esc(e.date)}</time></div><p>${esc(e.text)}</p><button class="text-link" data-entry-delete="${esc(e.id)}">Remove note</button></article>`).join(''):'<div class="empty"><h2>Your first note can be one sentence.</h2><p>“I can rearrange the equation and explain why the units work.” That counts as something worth remembering.</p><a href="#journey" class="text-link">Find one idea to explore →</a></div>'}</div></section>`;}
function v2About(){return `<section class="section about-body"><h2>What you can explore here</h2><p>The ${books.length}-book catalog is joined by twelve coursework bridges, six tabletop build briefs, two interactive mechanism models, five frontier dossiers, a night-reading shelf, and six philosophical lenses. Follow a reading route, try one small example, or keep a question in your field notes.</p><h2>How to interpret the learning content</h2><p>Worked examples are original teaching exercises with simplifying assumptions. They are not an accredited curriculum, an official transfer plan, or engineering designs for deployment. Frontier pages distinguish demonstrated foundations, research, and speculation. Publisher links establish the books’ stated arguments; they do not independently prove each political or empirical claim.</p><p>The philosophical lenses are perspectives to examine. They do not represent a required worldview or an assumption about the reader’s beliefs. A useful reading practice is to notice both what an argument explains and what it leaves unresolved.</p><h2>Additional sources</h2><div class="source-list">${philosophy.sources?.map(ext).join('')||''}</div><h2>A small record of a long journey</h2><p>Exploration marks are self-reported, not mastery scores. Field notes can hold a result, a question, or a reflection. Journey data has a separate browser-local store and backup from the book shelf. Import merges recognized exploration records and notes; matching note IDs are replaced by the imported entry. No cloud synchronization is provided.</p></section>`;}
function renderExtra(p,id){const funcs={home:basecamp,journey:journeyPage,frontiers:frontiersPage,ideas:ideasPage,night:nightPage,workbench:workbenchPage,projects:projectsPage,journal:journalPage};if(funcs[p])return funcs[p]();if(p==='lesson')return lessonPage(id);if(p==='frontier')return frontierPage(id);return null;}
document.addEventListener('click',e=>{const t=e.target.closest('button');if(!t)return;
 if(t.dataset.budget){journeyState.budget=Number(t.dataset.budget);persistJourney();document.querySelectorAll('[data-budget]').forEach(x=>{x.classList.toggle('active',Number(x.dataset.budget)===journeyState.budget);x.setAttribute('aria-pressed',String(Number(x.dataset.budget)===journeyState.budget));});$('#budget-copy').innerHTML=budgetCopy();}
 if(t.dataset.lens!==undefined){ideaIndex=Number(t.dataset.lens);document.querySelectorAll('[data-lens]').forEach(x=>{x.classList.toggle('active',Number(x.dataset.lens)===ideaIndex);x.setAttribute('aria-pressed',String(Number(x.dataset.lens)===ideaIndex));});$('#idea-panel').innerHTML=lensPanel();}
 if(t.dataset.practice){const id=t.dataset.practice;journeyState.practiced=journeyState.practiced.includes(id)?journeyState.practiced.filter(x=>x!==id):[...journeyState.practiced,id];const stored=persistJourney();t.textContent=journeyState.practiced.includes(id)?'✓ Explored · mark untried':'I tried the example ✓';t.setAttribute('aria-pressed',String(journeyState.practiced.includes(id)));if(stored)toast('Exploration saved. You can revisit this anytime.');}
 if(t.dataset.activeBridge){journeyState.active=t.dataset.activeBridge;if(persistJourney())toast('This is now your current thread at Basecamp.');}
 if(t.dataset.lab){labMode=t.dataset.lab;document.querySelectorAll('[data-lab]').forEach(x=>{x.classList.toggle('active',x.dataset.lab===labMode);x.setAttribute('aria-pressed',String(x.dataset.lab===labMode));});$('#lab-panel').innerHTML=labPanel();}
 if(t.hasAttribute('data-journey-export')){download(JSON.stringify({type:'builders-atlas-journey',version:2,journey:journeyState},null,2),'application/json','builders-atlas-journey-backup.json');toast('Journey backup downloaded.');}
 if(t.hasAttribute('data-journey-import'))$('#journey-import').click();
 if(t.dataset.entryDelete){journeyState.entries=journeyState.entries.filter(x=>x.id!==t.dataset.entryDelete);const stored=persistJourney();render();if(stored)toast('Note removed from this device.');}
});
document.addEventListener('input',e=>{const id=e.target.id;if(!id.startsWith('lab-'))return;const val=Number(e.target.value);if(id==='lab-angle'){labAngle=val;$('#angle-output').textContent=val+'°';}if(id==='lab-length'){labLength=val;$('#length-output').textContent=val+' cm';}if(id==='lab-effort'){labEffort=val;$('#effort-output').textContent=val.toFixed(2)+' m';}if(id==='lab-load'){labLoad=val;$('#load-output').textContent=val+' N';}$('#lab-visual').innerHTML=labMode==='arm'?armSVG(labAngle,labLength):leverSVG(labEffort,labLoad);$('#lab-result').innerHTML=labMode==='arm'?armResult():leverResult();});
document.addEventListener('submit',e=>{if(e.target.id!=='journal-form')return;e.preventDefault();const text=$('#entry-text').value.trim();if(!text)return;if(journeyState.entries.length>=300){toast('Journal full: export a backup, then remove old notes before adding more.');return;}journeyState.entries.unshift({id:'note-'+Date.now()+'-'+Math.random().toString(16).slice(2,8),date:new Date().toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}),kind:$('#entry-kind').value,text});journeyState.entries=journeyState.entries.slice(0,300);const stored=persistJourney();render();if(stored)toast('Field note saved.');});
document.addEventListener('change',async e=>{if(e.target.id!=='journey-import')return;const f=e.target.files[0];if(!f)return;try{if(f.size>12000000)throw Error('Size');const raw=JSON.parse(await f.text());if(raw.type!=='builders-atlas-journey'||raw.version!==2)throw Error('Format');const incoming=cleanJourney(raw.journey);const mergedEntries=[...new Map([...journeyState.entries,...incoming.entries].map(x=>[x.id,x])).values()];if(mergedEntries.length>300)throw Error('Capacity');journeyState={...incoming,practiced:[...new Set([...journeyState.practiced,...incoming.practiced])],entries:mergedEntries};const stored=persistJourney();render();if(stored)toast('Journey backup imported.');}catch(err){toast(err.message==='Capacity'?'Import would exceed 300 notes. Export a backup and remove old notes first.':'Choose a valid Reading Atlas journey backup.');}e.target.value='';});
